"""Embed images actually generated by ChatGPT in a single station import JSON.

python embed-generated-media.py input.json output.json --cover aussois=/path/generated.png
Add --logo aussois=/path/generated-badge.png only for the ANMSM fallback.
Official photographs are inspiration only: never pass one as generated input.
"""
import argparse
import base64
import io
import json
from pathlib import Path

from PIL import Image, ImageOps


def webp_bytes(path, role):
    limit = (80 if role == "cover" else 40) * 1024
    with Image.open(path) as source:
        source.load()
        alpha = "A" in source.getbands() or "transparency" in source.info
        image = ImageOps.exif_transpose(source).convert("RGBA" if alpha else "RGB")
    try:
        image.thumbnail((1600, 1600), Image.Resampling.LANCZOS)
        for _ in range(12):
            for quality in (88, 80, 72, 64, 56, 48, 40):
                encoded = io.BytesIO()
                image.save(encoded, "WEBP", quality=quality, method=6)
                if 0 < encoded.tell() <= limit:
                    return encoded.getvalue()
            if max(image.size) <= 64:
                break
            smaller = tuple(max(1, int(value * .8)) for value in image.size)
            resized = image.resize(smaller, Image.Resampling.LANCZOS)
            image.close()
            image = resized
        raise ValueError(f"Cannot fit {role} within {limit} bytes")
    finally:
        image.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input")
    parser.add_argument("output")
    parser.add_argument("--cover", action="append", default=[], metavar="SLUG=GENERATED_FILE")
    parser.add_argument("--logo", action="append", default=[], metavar="SLUG=GENERATED_FILE")
    args = parser.parse_args()
    batch = json.loads(Path(args.input).read_text())
    for role in ("cover", "logo"):
        for value in getattr(args, role):
            slug, filename = value.split("=", 1)
            asset = next(m for m in batch["media"] if m["station_slug"] == slug and m["role"] == role)
            for key in ("source_url", "source_page_url", "credit", "anmsm_external_id", "anmsm_media_id"):
                asset.pop(key, None)
            asset.update(status="found", format="file", source_kind="generated", source_provider="generated",
                         data_base64=base64.b64encode(webp_bytes(filename, role)).decode("ascii"))
    text = json.dumps(batch, ensure_ascii=False, indent=2)
    Path(args.output).write_text(text + "\n")


if __name__ == "__main__":
    main()
